    ):
        raise ValidationError(
            "body 字段 deactivated_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    try:
        _parse_utc_z(deactivated_at)
    except ValueError:
        raise ValidationError(
            "body 字段 deactivated_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )

    # ---- 锚点（缺失/吊销/公钥不可用 -> 200 valid:false，不写入）----
