            if anchor_row is not None
            else None
        )
    if anchor_row is None or anchor_status == "revoked":
        return {
            "valid": False,
            "reason": DEACTIVATION_ANCHOR_UNAVAILABLE_REASON,
        }
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return {
            "valid": False,
            "reason": DEACTIVATION_ANCHOR_UNAVAILABLE_REASON,
